  "check_code": "from pathlib import Path
import sqlite3
import re


def _db_path(ws):
    return Path(ws).parent / "system" / "appzen_ap_audit" / "state.db"


def _connect(ws):
    con = sqlite3.connect(_db_path(ws))
    con.row_factory = sqlite3.Row
    return con


def check_target_disposition(ws):
    with _connect(ws) as con:
        case = con.execute(
            "SELECT determination, confirmed_amount_cents, recovered_amount_cents, "
            "open_amount_cents, resolution_date, as_of_date "
            "FROM duplicate_candidate_cases WHERE case_id = ?",
            ("DPC-2025Q3-0064",),
        ).fetchone()
        event = con.execute(
            "SELECT reviewer_id, determination, confirmed_amount_cents, recovered_amount_cents, "
            "open_amount_cents, resolution_date, as_of_date "
            "FROM duplicate_case_resolution_log WHERE case_id = ? "
            "ORDER BY resolution_event_id DESC LIMIT 1",
            ("DPC-2025Q3-0064",),
        ).fetchone()
    expected_case = ("Requires Review", 0, 0, 0, "2025-10-24", "2025-10-24")
    expected_event = ("PERSON-MARCUS-GREEN",) + expected_case
    if case is None or tuple(case) != expected_case:
        return {"score": 0, "detail": f"target case post-state mismatch: {tuple(case) if case else None}"}
    if event is None or tuple(event) != expected_event:
        return {"score": 0, "detail": f"resolution log mismatch: {tuple(event) if event else None}"}
    return {"score": 1, "detail": "target case and Marcus Green resolution event match the required pending-review state"}


def check_pending_evidence(ws):
    with _connect(ws) as con:
        row = con.execute(
            "SELECT evidence_note FROM duplicate_candidate_cases WHERE case_id = ?",
            ("DPC-2025Q3-0064",),
        ).fetchone()
    if row is None:
        return {"score": 0, "detail": "target case not found"}
    raw_note = row[0].lower()
    note = re.sub(r"[^a-z0-9]+", " ", raw_note).strip()
    terms_ok = all(term in note for term in ("vendor", "statement", "pending"))
    # A note may mention prohibited dispositions while explicitly rejecting them
    # (for example, "before dispositioning as Confirmed Duplicate").  Reject
    # only affirmative claims, not these semantically equivalent negations.
    def _affirmed(term):
        for match in re.finditer(rf"\b{re.escape(term)}\b", raw_note):
            start = max(raw_note.rfind(mark, 0, match.start()) for mark in (".", "!", "?")) + 1
            preceding = raw_note[start:match.start()]
            if not re.search(
                r"\b(?:not|no|without|does not|do not|cannot|can't|never|pending|"
                r"rather than|before|insufficient|unconfirmed|unresolved)\b",
                preceding,
            ):
                return True
        return False

    excluded = any(_affirmed(term) for term in ("confirmed duplicate", "false positive", "recovered"))
    if not terms_ok or excluded or len(note.split()) < 6:
        return {"score": 0, "detail": "evidence note is not a substantive pending vendor-statement note"}
    return {"score": 1, "detail": "evidence note records pending vendor-statement confirmation without a final disposition claim"}


def check_other_cases_unchanged(ws):
    baseline = {
        "DPC-2025Q3-0041": ("False Positive", 0, 0, 0, "2025-09-12"),
        "DPC-2025Q3-0047": ("Confirmed Duplicate", 600000, 500000, 100000, "2025-10-03"),
        "DPC-2025Q3-0053": ("Confirmed Duplicate", 543210, 400000, 143210, "2025-10-15"),
        "DPC-2025Q3-0059": ("False Positive", 0, 0, 0, "2025-09-25"),
        "DPC-2025Q3-0070": ("False Positive", 0, 0, 0, "2025-09-29"),
        "DPC-2025Q3-0076": ("Confirmed Duplicate", 733245, 348370, 384875, "2025-10-24"),
        "DPC-2025Q3-0081": ("False Positive", 0, 0, 0, "2025-10-07"),
        "DPC-2025Q3-0088": ("False Positive", 0, 0, 0, "2025-10-11")
    }
    with _connect(ws) as con:
        rows = con.execute(
            "SELECT case_id, determination, confirmed_amount_cents, recovered_amount_cents, "
            "open_amount_cents, resolution_date FROM duplicate_candidate_cases "
            "WHERE case_id <> ? ORDER BY case_id",
            ("DPC-2025Q3-0064",),
        ).fetchall()
        recovery_target = con.execute(
            "SELECT COUNT(*) FROM payment_fingerprint_observations "
            "WHERE case_id = ? AND observation_type = 'Recovery'",
            ("DPC-2025Q3-0064",),
        ).fetchone()[0]
        target_nonrecovery = con.execute(
            "SELECT COUNT(*) FROM payment_fingerprint_observations "
            "WHERE case_id = ? AND observation_type <> 'Recovery'",
            ("DPC-2025Q3-0064",),
        ).fetchone()[0]
    actual = {row[0]: tuple(row[1:]) for row in rows}
    if actual != baseline or recovery_target != 0 or target_nonrecovery != 2:
        return {"score": 0, "detail": "an unrelated case or target observation population changed"}
    return {"score": 1, "detail": "other eight cases and target observation population are unchanged"}
